code.cpp:
class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int minPrice = prices[0];
        int best = 0;
        for (int i = 1; i < (int)prices.size(); i++) {
            if (prices[i] < minPrice) {
                minPrice = prices[i];
            } else {
                int profit = prices[i] - minPrice;
                if (profit > best) {
                    best = profit;
                }
            }
        }
        return best;
    }
};
